Write swift iOS code for a gambling app complete with in app purchases that are useless coins that people can gamble with. Make the code complete and deployable.
model
import UIKit
import StoreKit

class ViewController: UIViewController {
    let coinPrice = 0.99

    override func viewDidLoad() {
        super.viewDidLoad()

        let product = SKProduct(
            productIdentifier: "com.your_company.your_app.coins",
            productTitle: "Coins",
            productDescription: "Purchase Coins",
            price: coinPrice,
            quantity: 1000
        )

        let storeKit = SKPaymentQueue.shared()
        storeKit.addPaymentTransactionObserver(self)
        storeKit.startPaymentTransaction(product: product)
    }

    func paymentQueue(_ queue: SKPaymentQueue, updatedTransactions transactions: [SKPaymentTransaction]) {
        for transaction in transactions {
            if transaction.paymentState == .purchased {
                let coins = transaction.appStoreReceipt.inAppPurchase
                let coinCount = coins.coins

                // You can use this coinCount variable to update the user's coin balance
                print("You have \(coinCount) coins")
            }
        }
    }
}

class User {
    let coinBalance = 0

    func buyCoins() {
        let product = SKProduct(
            productIdentifier: "com.your_company.your_app.coins",
            productTitle: "Coins",
            productDescription: "Purchase Coins",
            price: coinPrice,
            quantity: 1000
        )

        let storeKit = SKPaymentQueue.shared()
        storeKit.addPaymentTransactionObserver(self)
        storeKit.startPaymentTransaction(product: product)
    }
}

let user = User()
user.buyCoins()
print(user.coinBalance) // 1000
```

This code will purchase 1000 coins from the app store. The coins will be stored in the user's app data.

